return function reconcileOriginalRows(raw, annex, Toml, U) {
 const parsed=Toml.parseToml(raw), current=parsed.value, ops=[], applied=[];
 const clone=x=>JSON.parse(JSON.stringify(x));
 for(const edit of annex.old_row_changes){
  if(edit.kind!=="boundary")throw Error("only exact old boundary reconciliation permitted");
  const hits=current.boundary.map((row,index)=>({row,index})).filter(x=>x.row.id===edit.old_row.id);
  if(hits.length!==1)throw Error("boundary identity is not unique: "+edit.old_row.id);
  const {row,index}=hits[0], next=clone(row);
  for(const key of new Set([...Object.keys(row),...Object.keys(edit.old_row)])){
   if(!edit.changed_fields.includes(key)&&!U.equal(row[key],edit.old_row[key]))throw Error("concurrent non-owned field conflict: "+edit.old_row.id+"."+key);
  }
  for(const field of edit.changed_fields){
   if(field==="product_callers"){
    const old=edit.old_row[field], wanted=edit.new_row[field];
    const removed=old.filter(p=>!wanted.includes(p)), added=wanted.filter(p=>!old.includes(p));
    if(!U.equal(removed,edit.removals)||!U.equal(added,edit.additions))throw Error("semantic caller delta inconsistent");
    const kept=old.filter(p=>!removed.includes(p));
    if(!kept.every(p=>row.product_callers.includes(p)))throw Error("unexplained original caller removal: "+edit.old_row.id);
    if(new Set(row.product_callers).size!==row.product_callers.length)throw Error("duplicate current caller");
    next.product_callers=row.product_callers.filter(p=>!removed.includes(p));
    for(const p of added)if(!next.product_callers.includes(p))next.product_callers.push(p);
   }else if(field==="definition_markers"){
    if(U.equal(row[field],edit.new_row[field]))continue;
    if(!U.equal(row[field],edit.old_row[field]))throw Error("definition-marker conflict: "+edit.old_row.id);
    next[field]=clone(edit.new_row[field]);
   }else throw Error("unapproved field: "+field);
  }
  const op=U.makeRowOp(raw,parsed,"boundary",index,next,edit.purpose);
  if(op)ops.push(op);
  applied.push({id:row.id,changed:!!op});
 }
 const post=U.applyExact(raw,ops), verified=Toml.parseToml(post).value;
 if(!U.equal(verified.protected_file,current.protected_file))throw Error("conjunctive protected rows changed");
 if(!U.equal(verified.privileged_inventory,current.privileged_inventory))throw Error("required ID inventory changed");
 if(!U.equal(verified.boundary.map(x=>x.id),current.boundary.map(x=>x.id)))throw Error("existing IDs/order changed");
 for(const key of Object.keys(current))if(key!=="boundary"&&!U.equal(current[key],verified[key]))throw Error("top-level value changed");
 return {post,ops,applied};
};
